contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint val) public {
        require(val < type(uint256).max);
        // Before initialization, SetMinSum succeeds and takes effect
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        // Initialize
        c.Initialized(); if (__ESBMC_reverted()) return;
        // After initialization, SetMinSum must revert
        bool r1;
        c.SetMinSum(val + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }
        // And SetLogFile must revert too
        bool r2;
        c.SetLogFile(address(this)); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }
        assert(r1 && r2 && c.MinSum() == val);
    }
}

