// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val) internal {
        vm.assume(val < type(uint256).max);
        try c.SetMinSum(val) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool r1;
        try c.SetMinSum(val + 1) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.SetLogFile(address(this)) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 && r2 && c.MinSum() == val);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
